/* 부분일치 검색 — 매장 이름을 다 다르게 부르기 때문에 앞글자만으로는 안 찾아집니다.
   "수내" 로도 "OK마트 (수내)" 가 나와야 합니다.
   관리업체로도 찾습니다 — "태일테크닉스" 로 그 업체가 관리하는 매장이 다 나옵니다. */
function searchStores(q, limit){
  const s = (q || '').trim();
  if(!s) return STORES.slice(0, limit || 8);
  const k = s.toLowerCase().replace(/\s+/g, '');
  const hit = STORES.filter(x =>
    (x.name + x.code + x.addr + (x.mgr || '') + (x.region || '')).toLowerCase().replace(/\s+/g, '').includes(k));
  /* 이름 앞부분이 맞는 것을 위로 */
  hit.sort((a, b) => {
    const ai = a.name.toLowerCase().replace(/\s+/g,'').indexOf(k);
    const bi = b.name.toLowerCase().replace(/\s+/g,'').indexOf(k);
    return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
  });
  return hit.slice(0, limit || 8);
}

/* 새 코드 채번 — 대리점은 2로 시작하는 6자리, 매장은 실데이터와 같은 7자리 */
function nextStoreCode(kind){
  if(kind === '대리점'){
    const nums = STORES.filter(s => s.code.startsWith('2')).map(s => Number(s.code));
    return String((nums.length ? Math.max(...nums) : 200000) + 1);
  }
  const nums = STORES.filter(s => !s.code.startsWith('2')).map(s => Number(s.code));
  return String((nums.length ? Math.max(...nums) : 0) + 1).padStart(7, '0');
}
